/* Skincare Luxury - Rose Luxury */
@import "tailwindcss";
@import "../../assets/masks.css";
@import "../../assets/animations.css";

:root {
  /* palette: rose luxury (light) */
  --background: #f5f5f5;
  --card: #ffffff;
  --foreground: #1c1c1c;
  --primary-cta: #511f1f;
  --primary-cta-text: #f5f5f5;
  --secondary-cta: #ffffff;
  --secondary-cta-text: #1c1c1c;
  --accent: #8f3838;
  --background-accent: #c9725c;

  /* border radius: soft */
  --radius: 1.5rem;

  /* content width: medium */
  --width-content-width: clamp(40rem, 72.5vw, 100rem);

  /* utilities */
  --vw-1_5: 1.5vw;
  --width-x-padding-mask-fade: 5vw;

  /* layout */
  --width-carousel-padding: calc((100vw - var(--width-content-width)) / 2 + 1px - 1rem);
  --width-carousel-padding-controls: calc((100vw - var(--width-content-width)) / 2 + 1px);
  --width-carousel-item-2: calc(var(--width-content-width) / 2 - var(--vw-1_5) / 2);
  --width-carousel-item-3: calc(var(--width-content-width) / 3 - var(--vw-1_5) / 3 * 2);
  --width-carousel-item-4: calc(var(--width-content-width) / 4 - var(--vw-1_5) / 4 * 3);

  /* type scale: medium */
  --text-2xs: clamp(0.465rem, 0.62vw, 0.62rem);
  --text-xs: clamp(0.54rem, 0.72vw, 0.72rem);
  --text-sm: clamp(0.615rem, 0.82vw, 0.82rem);
  --text-base: clamp(0.69rem, 0.92vw, 0.92rem);
  --text-lg: clamp(0.75rem, 1vw, 1rem);
  --text-xl: clamp(0.825rem, 1.1vw, 1.1rem);
  --text-2xl: clamp(0.975rem, 1.3vw, 1.3rem);
  --text-3xl: clamp(1.2rem, 1.6vw, 1.6rem);
  --text-4xl: clamp(1.5rem, 2vw, 2rem);
  --text-5xl: clamp(2.025rem, 2.75vw, 2.75rem);
  --text-6xl: clamp(2.475rem, 3.3vw, 3.3rem);
  --text-7xl: clamp(3rem, 4vw, 4rem);
  --text-8xl: clamp(3.5rem, 4.5vw, 4.5rem);
  --text-9xl: clamp(5.25rem, 7vw, 7rem);
}

/* Smaller laptops (< 14" MacBook) */
@media (max-width: 1440px) and (min-width: 769px) {
  :root {
    --width-content-width: 87.5vw;
  }
}

